import { test, expect } from "@playwright/test";
import { CartPage } from "../pages/cart.page";

test.describe("Cart and checkout", () => {

  // @story:TOOL-12
  // @ac:1
  // @design:D1
  // @type:functional
  // @technique:state-transition
  test("AC-1 Adding a product to the cart shows a confirmation and updates the cart icon count", async ({ page }, testInfo) => {
    const cartPage = new CartPage(page);

    await test.step("Given I navigate to the home page", async () => {
      await page.goto("/");
    });

    await test.step("Then the page displays \"Combination Pliers\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(cartPage.page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("When I navigate to the product page for \"Combination Pliers\"", async () => {
      await page.goto("/product/01M66P91DKD5X0W0AGEGGNJBVM");
    });

    await test.step("And I click \"Add to cart\"", async () => {
      await page.getByTestId("add-to-cart-quantity").waitFor({ state: "visible" }).catch(() => {});
      await page.getByRole("button", { name: "Add to cart" }).click();
    });

    await test.step("Then the page displays \"Product added to shopping cart.\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(cartPage.page.getByText("Product added to shopping cart.").first()).toBeVisible();
    });

    await test.step("And the cart icon count is shown in the header", async () => {
      // The cart quantity badge is shown in the nav header after adding to cart
      await expect(page.getByTestId("cart-quantity")).toBeVisible();
    });
  });

  // @story:TOOL-12
  // @ac:2
  // @design:D2
  // @type:functional
  // @technique:state-transition
  test("AC-2 Changing a line quantity in the cart updates the line total and cart total", async ({ page }, testInfo) => {
    const cartPage = new CartPage(page);

    await test.step("Given I navigate to the product page for \"Combination Pliers\"", async () => {
      await page.goto("/product/01M66P91DKD5X0W0AGEGGNJBVM");
    });

    await test.step("And I click \"Add to cart\"", async () => {
      await page.getByRole("button", { name: "Add to cart" }).click();
    });

    await test.step("And I navigate to the cart page", async () => {
      await page.goto("/checkout");
    });

    await test.step("Then the page displays \"Combination Pliers\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(cartPage.page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("When I set the cart line quantity to \"2\"", async () => {
      // Get the quantity input in the cart line and set it to 2
      const qtyInput = page.getByTestId("product-quantity");
      await qtyInput.fill("2");
      await qtyInput.press("Tab");
    });

    await test.step("Then the cart line total reflects quantity \"2\"", async () => {
      // Line total for Combination Pliers at qty 2 = $28.30 ($14.15 * 2)
      await expect(page.getByText("$28.30").first()).toBeVisible();
    });

    await test.step("And the cart total reflects the updated quantity", async () => {
      // Cart total should also show $28.30 (single item at qty 2)
      await expect(page.getByTestId("cart-total")).toBeVisible();
    });
  });

  // @story:TOOL-12
  // @ac:3
  // @design:D3
  // @type:functional
  // @technique:state-transition
  test("AC-3 Removing a line from the cart removes it and updates the cart total", async ({ page }, testInfo) => {
    const cartPage = new CartPage(page);

    await test.step("Given I navigate to the product page for \"Combination Pliers\"", async () => {
      await page.goto("/product/01M66P91DKD5X0W0AGEGGNJBVM");
    });

    await test.step("And I click \"Add to cart\"", async () => {
      await page.getByRole("button", { name: "Add to cart" }).click();
    });

    await test.step("And I navigate to the cart page", async () => {
      await page.goto("/checkout");
    });

    await test.step("Then the page displays \"Combination Pliers\"", async () => {
      // @bdd2pw lane=rule rule=rule-50
      await expect(cartPage.page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("When I click the remove line button", async () => {
      await page.getByRole("button", { name: "Remove" }).first().click();
    });

    await test.step("Then the page does not display \"Combination Pliers\"", async () => {
      await expect(page.getByText("Combination Pliers")).not.toBeVisible();
    });

    await test.step("And the cart total is shown", async () => {
      // After removal the cart shows an empty state or $0.00 total
      // The cart total element (or empty cart message) should still be present
      await expect(
        page.getByText("$0.00").or(page.getByText("Your cart is empty")).or(page.getByTestId("cart-subtotal"))
      ).toBeVisible();
    });
  });

  // @story:TOOL-12
  // @design:D4
  // @type:accessibility
  // @technique:checklist-based
  test("AC-accessibility Cart page passes accessibility checks", async ({ page }, testInfo) => {
    const cartPage = new CartPage(page);

    await test.step("Given I navigate to the product page for \"Combination Pliers\"", async () => {
      await page.goto("/product/01M66P91DKD5X0W0AGEGGNJBVM");
    });

    await test.step("And I click \"Add to cart\"", async () => {
      await page.getByRole("button", { name: "Add to cart" }).click();
    });

    await test.step("And I navigate to the cart page", async () => {
      await page.goto("/checkout");
    });

    await test.step("Then the page passes axe accessibility checks", async () => {
      // @bdd2pw lane=rule rule=rule-49
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page: cartPage.page })
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(axeResults.violations.map((v) => v.id).sort(), `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`).toEqual([]);
    });
  });
});
